import Foundation
import Testing
@testable import PixlLibrary

/// The stage 4 golden vectors (`servedvec`, `gate2`, `assistant`): the served feature vector's quantisation and the replay that trains
/// on it, the gate's 1% margin with the test 6 interval, and the pure rules of Ask Taizo's tools (`AssistantRules`, `Grounding`).
/// Generated by the Android repo's `./gradlew :brain:generateGolden`, copied here unchanged. The README beside the files says how
/// each `fn` is replayed.
@Suite("Brain stage 4 golden vectors (brainMatchesAndroid)")
struct BrainStage4GoldenTests {
    typealias G = BrainGoldenTests
    typealias M2 = BrainStage2bM2GoldenTests
    typealias Value = BrainJson.Value

    static func strings(_ v: Value, _ k: String) -> [String] { G.array(v, k).map { $0.stringValue ?? "" } }
    static func ints(_ v: Value, _ k: String) -> [Int] { G.array(v, k).map { Int($0.bareLong ?? 0) } }
    static func optStrings(_ v: Value, _ k: String) -> [String]? { v[k]?.isNull == false ? strings(v, k) : nil }

    static func writeStrings(_ w: inout BrainJson.Writer, _ name: String, _ values: [String]) {
        w.beginArray(name)
        for s in values { w.stringItem(s) }
        w.endArray()
    }

    static func writeInts(_ w: inout BrainJson.Writer, _ name: String, _ values: [Int]) {
        w.beginArray(name)
        for i in values { w.intItem(i) }
        w.endArray()
    }

    static func writeDoubles(_ w: inout BrainJson.Writer, _ name: String, _ values: [Double]) {
        w.beginArray(name)
        for d in values { w.doubleItem(d) }
        w.endArray()
    }

    // MARK: servedvec.jsonl

    @Test func servedVectorMatchesAndroid() throws {
        var report = G.Report(file: "servedvec.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("servedvec.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "quantize":
                let bytes = ServedVector.quantize(M2.doubles(i, "x"))
                let back = ServedVector.dequantize(bytes) ?? []
                report.record(c, c.matches { $0.string("hex", ServedVector.toHex(bytes)); Self.writeDoubles(&$0, "back", back) })
            case "hexBad":
                report.record(c, c.matches { $0.bool("accepted", ServedVector.fromHex(G.string(i, "hex")) != nil) })
            case "servedReplay":
                let events = G.events(i, "events")
                let nowMs = G.long(i, "nowMs")
                let withVec = LearnReplay.run(events, facts: .empty, nowMs: nowMs, likedRids: [], tzNowMin: 0)
                let stripped = events.map { e -> PlayEvent in
                    var copy = e
                    copy.servedX = nil
                    return copy
                }
                let without = LearnReplay.run(stripped, facts: .empty, nowMs: nowMs, likedRids: [], tzNowMin: 0)
                let learnedHash = M2.hashDoubles(withVec.predictions.learned)
                let withoutHash = M2.hashDoubles(without.predictions.learned)
                #expect(learnedHash != withoutHash, "a served vector must change what the learner predicts")
                report.record(c, c.matches {
                    Self.writeDoubles(&$0, "m", withVec.model.m); Self.writeDoubles(&$0, "q", withVec.model.q)
                    $0.long("updates", withVec.model.updates); $0.int("graded", withVec.predictions.size)
                    $0.long("learnedHash", learnedHash)
                    $0.long("priorHash", M2.hashDoubles(withVec.predictions.prior))
                    $0.long("learnedHashWithout", withoutHash)
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 30)
        #expect(counts["quantize"] == 24)
        #expect(counts["hexBad"] == 5)
        #expect(counts["servedReplay"] == 3)
    }

    @Test func aServedVectorSurvivesTheEventLine() throws {
        let hex = String(repeating: "0a", count: ServedVector.bytes)
        var e = PlayEvent(eventId: 7, origin: Origin.live, rid: 1, primaryAid: 2, startedAtMs: 1_000, playedMs: 5)
        #expect(!e.encode().contains("servedX"), "a play without a served vector keeps the stage 1 line")
        e.servedX = try #require(ServedVector.fromHex(hex))
        let line = e.encode()
        #expect(line.contains("\"servedX\":\"\(hex)\""))
        #expect(PlayEvent.decode(line)?.servedX == e.servedX)
        // A stage 1 line has no key: it reads as nil, not as a failure.
        e.servedX = nil
        #expect(PlayEvent.decode(e.encode())?.servedX == nil)
        // A text of the wrong length reads as no vector.
        #expect(ServedVector.fromHex("0a0a") == nil)
        #expect(ServedVector.dequantize([1, 2, 3]) == nil)
    }

    // MARK: gate2.jsonl

    @Test func gateRuleMatchesAndroid() throws {
        var report = G.Report(file: "gate2.jsonl")
        var n = 0
        for c in try G.cases("gate2.jsonl") {
            n += 1
            let i = c.input
            guard c.fn == "gate2" else {
                report.record(c, false)
                continue
            }
            let summary = Gate.Summary(plays: Int(G.int(i, "plays")), playsTotal: Int(G.int(i, "playsTotal")),
                                       logLossLearned: G.double(i, "llLearned"), logLossPrior: G.double(i, "llPrior"),
                                       accLearned: 0.6, accPrior: 0.55, accLearnedBefore: nil, accPriorBefore: nil)
            let prev = Gate.State(useLearned: G.bool(i, "useLearned"), winStreak: Int(G.int(i, "winStreak")), atMs: G.long(i, "atMs"))
            let next = Gate.decide(prev, summary, nowMs: G.long(i, "nowMs"), intervalAboveZero: G.bool(i, "intervalAboveZero"))
            report.record(c, c.matches {
                $0.bool("useLearned", next.useLearned); $0.int("winStreak", next.winStreak); $0.long("atMs", next.atMs)
                $0.bool("clearlyBetter", summary.learnedClearlyBetter)
            })
        }
        report.verify(atLeast: 60)
        #expect(n == 60)
    }

    // MARK: assistant.jsonl

    static func writeQuery(_ w: inout BrainJson.Writer, _ q: AssistantRules.Query) {
        w.string("title", q.title)
        writeStrings(&w, "seedRefs", q.seedRefs)
        writeInts(&w, "genreIds", q.genreIds)
        writeInts(&w, "moodIds", q.moodIds)
        w.int("yearFrom", q.yearFrom); w.int("yearTo", q.yearTo)
        w.string("energy", q.energy); w.string("tempo", q.tempo); w.string("novelty", q.novelty)
        w.int("noveltySharePct", q.noveltySharePct); w.int("count", q.count)
        writeStrings(&w, "excludeArtistRefs", q.excludeArtistRefs)
        writeInts(&w, "excludeGenreIds", q.excludeGenreIds)
    }

    /// The query a `passes` or `chips` line starts from. In a `passes` line the key `energy` is written twice (the request's word, then
    /// the candidate's number): the parser keeps the last, so the word is read from the line's text.
    static func query(_ i: Value, line: String) -> AssistantRules.Query {
        var energy = G.string(i, "energy")
        if i["energy"]?.stringValue == nil, let r = line.range(of: "\"energy\":\"") {
            energy = String(line[r.upperBound...].prefix { $0 != "\"" })
        }
        return AssistantRules.Query(
            title: G.string(i, "title"), seedRefs: strings(i, "seedRefs"), genreIds: ints(i, "genreIds"), moodIds: ints(i, "moodIds"),
            yearFrom: Int(G.int(i, "yearFrom")), yearTo: Int(G.int(i, "yearTo")), energy: energy, tempo: G.string(i, "tempo"),
            novelty: G.string(i, "novelty"), noveltySharePct: Int(G.int(i, "noveltySharePct")), count: Int(G.int(i, "count")),
            excludeArtistRefs: strings(i, "excludeArtistRefs"), excludeGenreIds: ints(i, "excludeGenreIds"))
    }

    static func writeChips(_ w: inout BrainJson.Writer, _ name: String, _ chips: [AssistantRules.Chip]) {
        w.beginArray(name)
        for o in chips {
            w.beginArray(); w.intItem(o.kind); w.stringItem(o.ref); w.intItem(o.genreId); w.endArray()
        }
        w.endArray()
    }

    @Test func assistantRulesMatchAndroid() throws {
        var report = G.Report(file: "assistant.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("assistant.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "parseRef":
                let r = AssistantRules.parseRef(G.string(i, "ref"))
                report.record(c, c.matches {
                    if let r { $0.int("kind", r.kind) } else { $0.nullValue("kind") }
                    if let r { $0.string("id", r.id) } else { $0.nullValue("id") }
                })
            case "normalize":
                let q = AssistantRules.normalize(
                    title: i["title"]?.stringValue, seedRefs: Self.optStrings(i, "seeds"),
                    genreIds: i["genres"]?.isNull == false ? Self.ints(i, "genres") : nil,
                    moodIds: i["moods"]?.isNull == false ? Self.ints(i, "moods") : nil,
                    yearFrom: Int(G.int(i, "from")), yearTo: Int(G.int(i, "to")), energy: i["energy"]?.stringValue,
                    tempo: i["tempo"]?.stringValue, novelty: i["novelty"]?.stringValue, noveltySharePct: Int(G.int(i, "share")),
                    count: Int(G.int(i, "count")), excludeArtistRefs: Self.optStrings(i, "exclude"), minCount: Int(G.int(i, "min")),
                    maxCount: Int(G.int(i, "max")), defaultCount: Int(G.int(i, "def")))
                report.record(c, c.matches { Self.writeQuery(&$0, q) })
            case "passes":
                let q = Self.query(i, line: c.line)
                let facts = AssistantRules.Facts(
                    year: Int(G.int(i, "year")), genreIds: Self.ints(i, "have"), novel: G.bool(i, "novel"), bpm: Int(G.int(i, "bpm")),
                    artistKey: G.string(i, "artist"), energy: Int(G.int(i, "energy")), moodIds: Self.ints(i, "moodHave"))
                let ctx = AssistantRules.FilterContext(
                    tempoKnown: G.bool(i, "tempoKnown"), energyKnown: G.bool(i, "energyKnown"), moodKnown: G.bool(i, "moodKnown"),
                    energyRef: Int(G.int(i, "energyRef")), excludedArtists: Self.strings(i, "excluded"))
                let base = G.double(i, "base")
                report.record(c, c.matches {
                    $0.bool("passes", AssistantRules.passes(q, facts, ctx))
                    $0.double("share", AssistantRules.noveltyShare(q, base: base))
                    Self.writeStrings(&$0, "unsupported", AssistantRules.unsupportedFilters(q, ctx))
                })
            case "chips":
                var q = Self.query(i, line: c.line)
                for step in G.array(i, "steps") {
                    let s = step.arrayValue ?? []
                    q = AssistantRules.applyChip(q, AssistantRules.Chip(kind: Int(s[0].bareLong ?? 0), ref: s[1].stringValue ?? "",
                                                                        genreId: Int(s[2].bareLong ?? 0)))
                }
                let offered = AssistantRules.chipsFor(q, topArtistRef: "yt:aaaaaaaaaaa", topGenreId: 5)
                report.record(c, c.matches { Self.writeQuery(&$0, q); Self.writeChips(&$0, "offered", offered) })
            case "topFactors":
                let out = AssistantRules.topFactors(M2.doubles(i, "x"), Ranker.weights(p0: G.double(i, "p0")))
                report.record(c, c.matches {
                    $0.beginArray("factors")
                    for f in out { $0.beginArray(); $0.stringItem(f.name); $0.intItem(f.up ? 1 : 0); $0.endArray() }
                    $0.endArray()
                })
            case "grounding":
                var reg = Grounding.Registry()
                for n in Self.strings(i, "names") { reg.addName(n) }
                for t in Self.strings(i, "texts") { reg.addText(t) }
                let v = Grounding.check(G.string(i, "reply"), reg, userText: G.string(i, "user"), placeholder: "(unverified)",
                                        dropUngroundedNumbers: G.bool(i, "drop"))
                report.record(c, c.matches {
                    $0.string("cleaned", v.cleaned)
                    Self.writeStrings(&$0, "ungroundedNames", v.ungroundedNames)
                    Self.writeStrings(&$0, "ungroundedNumbers", v.ungroundedNumbers)
                })
            case "numbers":
                let text = G.string(i, "text")
                report.record(c, c.matches {
                    Self.writeStrings(&$0, "all", Grounding.numbersIn(text))
                    Self.writeStrings(&$0, "stat", Grounding.listenerNumbers(text).map(\.token))
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 90)
        #expect(counts["parseRef"] == 13)
        #expect(counts["normalize"] == 6)
        #expect(counts["passes"] == 48)
        #expect(counts["chips"] == 10)
        #expect(counts["topFactors"] == 8)
        #expect(counts["grounding"] == 8)
        #expect(counts["numbers"] == 3)
    }

    @Test func stage4FilesAreInTheManifest() throws {
        let manifest = String(decoding: try G.fixtureData("MANIFEST.sha256"), as: UTF8.self)
        for name in ["servedvec.jsonl", "gate2.jsonl", "assistant.jsonl"] {
            #expect(manifest.contains("  \(name)"), "\(name) is not in MANIFEST.sha256")
        }
    }
}
